//! Local harness contracts exercise the actual executable and native indexes.
//! The measured 60-file fixture is not release or tail-latency certification.
use cc_eval::benchmark::{
    mutation_case,
    p8_scale::{
        self, CapacityProfile, ColdStudy, Profile, ProfileStudy, ScalePlan, ScaleShard, StageScope,
        RELEASE_SCALES,
    },
};
use serde_json::{json, Value};
use std::{collections::BTreeSet, path::Path};

fn binary() -> &'static Path {
    Path::new(env!("CARGO_BIN_EXE_p8-scale"))
}

#[test]
fn matrix_and_release_admission_are_explicit_and_bounded() {
    assert_eq!(RELEASE_SCALES, [1_000, 5_000, 10_000, 50_000, 100_000]);
    let mut plan = ScalePlan::default();
    plan.validate().unwrap();
    plan.files = RELEASE_SCALES.to_vec();
    plan.validate().unwrap();
    for files in [vec![59], vec![100_001], vec![1000, 1000]] {
        plan.files = files;
        assert!(plan.validate().is_err());
    }
    plan.files = vec![1000];
    plan.profile = Profile::Release;
    assert!(
        plan.validate().is_err(),
        "one debug sample cannot certify release"
    );
}

#[test]
fn named_scale_capacity_is_explicit_and_cannot_relax_fanout_pressure() {
    let mut plan = ScalePlan::default();
    assert!(plan.capacity_profile.is_none());
    assert_eq!(plan.fanout_budgets(), (2, 64));
    assert!(serde_json::to_value(&plan)
        .unwrap()
        .get("capacity_profile")
        .is_none());
    plan.capacity_profile = Some(CapacityProfile::ScaleCapacityV1);
    plan.dirty_budget = 200;
    plan.max_resume_builds = 1024;
    assert_eq!(plan.fanout_budgets(), (8, 128));
    assert!(plan
        .validate()
        .unwrap_err()
        .to_string()
        .contains("scale_capacity_v1 requires"));
    plan.profile = Profile::Release;
    plan.files = vec![1000];
    plan.repetitions = 30;
    plan.shard = Some(ScaleShard {
        index: 0,
        count: 30,
    });
    if cfg!(debug_assertions) {
        assert!(plan
            .validate()
            .unwrap_err()
            .to_string()
            .contains("release eval build"));
    } else {
        plan.validate().unwrap();
        assert_eq!(plan.repetition_range().unwrap(), 0..1);
    }
    plan.dirty_budget = 201;
    assert!(plan
        .validate()
        .unwrap_err()
        .to_string()
        .contains("scale_capacity_v1 requires"));
    plan.dirty_budget = 200;
    plan.shard = Some(ScaleShard { index: 0, count: 6 });
    assert!(plan
        .validate()
        .unwrap_err()
        .to_string()
        .contains("scale_capacity_v1 requires"));
}

#[test]
fn named_wide_dirty_profile_is_distinct_and_preserves_legacy_budgets() {
    let mut plan = ScalePlan {
        profile: Profile::Release,
        capacity_profile: Some(CapacityProfile::ScaleWideDirtyV1),
        files: vec![1000],
        repetitions: 30,
        shard: Some(ScaleShard {
            index: 0,
            count: 30,
        }),
        dirty_budget: 4096,
        max_resume_builds: 1024,
        deadline_ms: 18_000_000,
        max_output_bytes: 512 * 1024 * 1024,
        ..ScalePlan::default()
    };
    let encoded = serde_json::to_value(&plan).unwrap();
    assert_eq!(encoded["capacity_profile"], "scale_wide_dirty_v1");
    let decoded: ScalePlan = serde_json::from_value(encoded).unwrap();
    assert_eq!(decoded.capacity_profile, plan.capacity_profile);
    assert_eq!(decoded.dirty_budget, 4096);
    assert_eq!(plan.fanout_budgets(), (8, 128));
    if cfg!(debug_assertions) {
        assert!(plan
            .validate()
            .unwrap_err()
            .to_string()
            .contains("release eval build"));
    } else {
        plan.validate().unwrap();
        assert_eq!(plan.repetition_range().unwrap(), 0..1);
    }
    for budget in [200, 4095, 4097] {
        plan.dirty_budget = budget;
        assert!(plan
            .validate()
            .unwrap_err()
            .to_string()
            .contains("scale_wide_dirty_v1 requires"));
    }
    plan.dirty_budget = 4096;
    plan.capacity_profile = Some(CapacityProfile::ScaleCapacityV1);
    assert!(plan
        .validate()
        .unwrap_err()
        .to_string()
        .contains("scale_capacity_v1 requires"));
    plan.capacity_profile = Some(CapacityProfile::ScaleWideDirtyV1);
    plan.max_resume_builds = 1023;
    assert!(plan
        .validate()
        .unwrap_err()
        .to_string()
        .contains("scale_wide_dirty_v1 requires"));
    plan.max_resume_builds = 1024;
    plan.shard = Some(ScaleShard { index: 0, count: 6 });
    assert!(plan
        .validate()
        .unwrap_err()
        .to_string()
        .contains("scale_wide_dirty_v1 requires"));
}

#[test]
fn wide_dirty_cli_rejects_cross_profile_budgets_before_starting_work() {
    let root = tempfile::tempdir().unwrap();
    for (profile, budget) in [
        ("scale_wide_dirty_v1", "200"),
        ("scale_capacity_v1", "4096"),
    ] {
        let output = root.path().join(profile);
        let result = std::process::Command::new(binary())
            .args([
                "--profile",
                "release",
                "--capacity-profile",
                profile,
                "--files",
                "1000",
                "--repetitions",
