                repetitions,
                "--shard-index",
                "0",
                "--shard-count",
                repetitions,
                "--skip-fanout",
                "--dirty-budget",
                "200",
                "--max-resume-builds",
                "1024",
                "--batch-sizes",
                "1,10,100,1000",
                "--fanouts",
                "1,4,16,64,128",
                "--deadline-ms",
                "18000000",
                "--max-output-bytes",
                "536870912",
                "--output",
            ])
            .arg(&out)
            .output()
            .unwrap();
        assert_eq!(result.status.code(), Some(2), "{result:?}");
        assert!(!out.exists());
    }
}
